from flask import Flask
app = Flask(__name__)

@app.get("/items/<int:item_id>")
def item(item_id):
    return {"id": item_id}

c = app.test_client()
print(c.get("/items/5").status_code, c.get("/items/five").status_code)

@app.get("/page")
def page():
    limit = request.args.get("limit", 10, type=int)
    return {"limit": limit}

@app.post("/cart/<item>")
def add(item):
    cart = session.setdefault("cart", {})
    cart[item] = cart.get(item, 0) + 1
    return cart
